            a[i][0] = safeAdd(safeMul(a[i - 1][0], 2, LIMIT), 1, LIMIT);
        }
        for (int i = 1; i < N; i++) {
            for (int j = 1; j < N; j++) {
                long g = gcd(a[i - 1][j], a[i][j - 1]);
                long l = safeMul(a[i - 1][j] / g, a[i][j - 1], LIMIT - 1);
                a[i][j] = safeAdd(l, 1, LIMIT);
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j > 0) sb.append(' ');
                sb.append(a[i][j]);
            }
            sb.append('\n');
        }

        System.out.print(sb.toString());
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static long safeMul(long a, long b, long limit) {
        if (a == 0 || b == 0) return 0;
        if (a > limit / b) return limit;
        return a * b;
    }

    static long safeAdd(long a, long b, long limit) {
        if (a > limit - b) return limit;
        return a + b;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

